pub fn json_field_int(obj: Rc<JsonValue>, key: String) -> Rc<JsonFieldRead<i64>> {
    match (*json_field(obj, key.clone())).clone() {
    JsonFieldRead::FieldAbsent => Rc::new(JsonFieldRead::FieldAbsent),
    JsonFieldRead::FieldMalformed { cause: c, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: c.clone(),
}),
    JsonFieldRead::FieldRead { value: v, .. } => match (*v.clone()).clone() {
    JsonValue::JsonNumber { lexeme: lx, .. } => match v1_rt::parse_int(lx.clone()) {
    Some(n) => Rc::new(JsonFieldRead::FieldRead {
    value: n.clone(),
}),
    std::option::Option::None => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " carries the number lexeme ".to_string(), lx.clone(), ", which is not an integer".to_string()]), "".to_string()),
}),
},
    JsonValue::JsonNull => Rc::new(JsonFieldRead::FieldAbsent),
    JsonValue::JsonBool { value: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is a bool where a number was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonString { value: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is a string where a number was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonArray { elements: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is an array where a number was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonObject { members: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is an object where a number was expected".to_string()]), "".to_string()),
}),
},
}
}

pub fn json_field_nat(obj: Rc<JsonValue>, key: String) -> Rc<JsonFieldRead<i64>> {
    match (*json_field_int(obj, key.clone())).clone() {
    JsonFieldRead::FieldAbsent => Rc::new(JsonFieldRead::FieldAbsent),
    JsonFieldRead::FieldMalformed { cause: c, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: c.clone(),
}),
    JsonFieldRead::FieldRead { value: n, .. } => if (n.clone() < 0) {
        Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is ".to_string(), crate::std_integer::int_to_decimal_string(n.clone()), ", which no unsigned carrier can hold; it is refused rather than clamped".to_string()]), "".to_string()),
})
    } else {
        Rc::new(JsonFieldRead::FieldRead {
    value: n.clone(),
})
    },
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct JsonStringListAcc {
    pub values: Rc<Vec<String>>,
    pub cause: Option<String>,
}

pub fn json_string_list_step(acc: Rc<JsonStringListAcc>, key: String, v: Rc<JsonValue>) -> Rc<JsonStringListAcc> {
    match acc.cause.clone() {
    Some(_) => acc,
    std::option::Option::None => match (*v.clone()).clone() {
    JsonValue::JsonString { value: s, .. } => Rc::new(JsonStringListAcc {
    values: v1_rt::concat(acc.values.clone(), Rc::new(vec![s.clone()])),
    cause: std::option::Option::None,
}),
    JsonValue::JsonNull => Rc::new(JsonStringListAcc {
    values: acc.values.clone(),
    cause: Some(crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " holds a null where every element must be a string".to_string()]), "".to_string())),
}),
    JsonValue::JsonBool { value: _, .. } => Rc::new(JsonStringListAcc {
    values: acc.values.clone(),
    cause: Some(crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " holds a bool where every element must be a string".to_string()]), "".to_string())),
}),
    JsonValue::JsonNumber { lexeme: _, .. } => Rc::new(JsonStringListAcc {
    values: acc.values.clone(),
    cause: Some(crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " holds a number where every element must be a string".to_string()]), "".to_string())),
}),
    JsonValue::JsonArray { elements: _, .. } => Rc::new(JsonStringListAcc {
    values: acc.values.clone(),
    cause: Some(crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " holds an array where every element must be a string".to_string()]), "".to_string())),
}),
    JsonValue::JsonObject { members: _, .. } => Rc::new(JsonStringListAcc {
    values: acc.values.clone(),
    cause: Some(crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " holds an object where every element must be a string".to_string()]), "".to_string())),
}),
},
}
}

pub fn json_field_string_list(obj: Rc<JsonValue>, key: String) -> Rc<JsonFieldRead<Rc<Vec<String>>>> {
    match (*json_field(obj, key.clone())).clone() {
    JsonFieldRead::FieldAbsent => Rc::new(JsonFieldRead::FieldAbsent),
    JsonFieldRead::FieldMalformed { cause: c, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: c.clone(),
}),
    JsonFieldRead::FieldRead { value: v, .. } => match (*v.clone()).clone() {
    JsonValue::JsonArray { elements: es, .. } => {
        let acc = es.iter().cloned().fold(Rc::new(JsonStringListAcc {
    values: Rc::new(vec![]),
    cause: std::option::Option::None,
}), |a: Rc<JsonStringListAcc>, e: Rc<JsonValue>| json_string_list_step(a, key.clone(), e.clone()));
match acc.cause.clone() {
    Some(c) => Rc::new(JsonFieldRead::FieldMalformed {
    cause: c.clone(),
}),
    std::option::Option::None => Rc::new(JsonFieldRead::FieldRead {
    value: acc.values.clone(),
}),
}
},
    JsonValue::JsonNull => Rc::new(JsonFieldRead::FieldAbsent),
    JsonValue::JsonBool { value: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is a bool where an array was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonNumber { lexeme: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is a number where an array was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonString { value: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is a string where an array was expected".to_string()]), "".to_string()),
}),
    JsonValue::JsonObject { members: _, .. } => Rc::new(JsonFieldRead::FieldMalformed {
    cause: crate::std_algebra::string_concat_join(Rc::new(vec![key.clone(), " is an object where an array was expected".to_string()]), "".to_string()),
}),
},
}
}

pub fn json_field_value<T: Clone>(r: Rc<JsonFieldRead<T>>) -> Option<T> {
    match (*r.clone()).clone() {
    JsonFieldRead::FieldAbsent => std::option::Option::None,
    JsonFieldRead::FieldMalformed { cause: _, .. } => std::option::Option::None,
    JsonFieldRead::FieldRead { value: v, .. } => Some(v.clone()),
}
}

pub fn json_field_cause<T: Clone>(r: Rc<JsonFieldRead<T>>) -> Option<String> {
    match (*r.clone()).clone() {
    JsonFieldRead::FieldAbsent => std::option::Option::None,
    JsonFieldRead::FieldMalformed { cause: c, .. } => Some(c.clone()),
    JsonFieldRead::FieldRead { value: _, .. } => std::option::Option::None,
}
}
